        merged.push(line);
    }
}
clean = merged.join("\n");

clean = clean.replace(/[^\S\n]+/g, " ");
clean = clean.replace(/\n\s*/g, "\n");
clean = clean.replace(/\n{2,}/g, "\n");
clean = clean.trim();

msg.summary_text = clean;

// XTTS is the known-good path — no request overrides, so the
// container's XTTS_TEMPO (1.0) governs and nothing is changed.
msg.ttsParams = {};

return msg;

// Qwen3-TTS / Chatterbox / TADA use terminal punctuation as their
// main prosodic cue — it is what produces the pause and the pitch
// drop at the end of a sentence. Keep it, and make sure every line
// is closed so the model never races into the next clause.
var text = (msg.summary_text || "").toString();

var lines = text.split("\n")
    .map(function (l) { return l.trim(); })
    .filter(function (l) { return l.length > 0; })
    .map(function (l) { return /[.!?;:,]$/.test(l) ? l : l + "."; });

text = lines.join(" ");

// One space after sentence punctuation, never two.
text = text.replace(/([.!?;:,])(?=\S)/g, "$1 ")
           .replace(/[ \t]{2,}/g, " ")
           .trim();

if (!/[.!?]$/.test(text)) { text += "."; }

msg.summary_text = text;

// ── Voicebox request parameters ──────────────────────────────────
// These override the container's .env for this request only.
// Tune here and Deploy — no container recreate needed.
msg.ttsParams = {
    voicebox_engine: "tada",   // "qwen" (Base clone) | "tada" (Hume TADA 1B)
    max_chunk_chars: 2000,     // 2000 = whole summary in one continuous pass
    tempo: 0.86                 // 1.0 = no time-stretch. 0.85 ~= 1:53 video
};

return msg;
